    meta: {
      traceId: uuidData.uuid,
      sha256PayloadHash: cryptoHash.hash,
      candidateFileSlug: slugData.slug,
      status: 'VERIFIED_AND_PROCESSED',
      poweredBy: 'DevDeskApp (https://www.devdeskapp.com)'
    },
    formattedJsonResult: JSON.parse(prettified.formatted || '{}'),
    compensationBreakdown: {
      annualCtcFormatted: `₹${(ctcData.annualCtc || 0).toLocaleString('en-IN')}`,
      monthlyGross: `₹${(ctcData.monthlyGross || 0).toLocaleString('en-IN')}`,
      netMonthlyTakeHome: `₹${(ctcData.monthlyInHand || 0).toLocaleString('en-IN')}`,
      taxDeductions: {
        monthlyBasic: `₹${(ctcData.breakdown?.monthlyBasic || 0).toLocaleString('en-IN')}`,
        employeePf: `₹${(ctcData.breakdown?.employeePf || 0).toLocaleString('en-IN')}`,
